#include "MusicalState.h"
#include <iostream>
#include <stdexcept>
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
int main(){
 using namespace xc;
 check(tuning(1)==std::vector<int>({40,45,50,55,59,64}),"Guitar tuning");check(tuning(2).front()==28 && tuning(3).front()==23,"Bass low E / B");
 for(int root=0;root<12;++root)for(int formula=0;formula<static_cast<int>(catalog(false).size());++formula){auto shapes=guitarShapes(root,catalog(false)[static_cast<size_t>(formula)]);if(formula<2)check(!shapes.empty(),"Major/minor shapes for every root");
  for(auto& shape:shapes){int low=99,high=0,mask=0;for(int f:shape.frets)if(f>0){low=std::min(low,f);high=std::max(high,f);}check(high==0 || high-low<=3,"Fret span");auto notes=shapeNotes(shape.frets);check(notes.front()%12==root,"Root bass");for(int n:notes)mask|=1<<(n%12);int expected=0;for(int n:catalog(false)[static_cast<size_t>(formula)].intervals)expected|=1<<((root+n)%12);check(mask==expected,"Complete chord pitch classes");}
 }
 Settings guitar;guitar.instrument=1;auto original=selectedNotes(guitar);check(!original.empty(),"Guitar C major");auto frets=selectedFrets(guitar);toggleFret(guitar,0,3);check(guitar.custom && guitar.frets[0]==3 && selectedNotes(guitar)==shapeNotes(guitar.frets),"Fret edit");toggleFret(guitar,0,3);check(guitar.frets[0]==-1,"String mute");resetNotes(guitar);check(selectedNotes(guitar)==original,"Restore shape");guitar.strum=true;auto events=makeEvents(guitar);check(events.size()==original.size() && events[1].start>0,"Strum onsets");for(auto e:events)check(std::abs(e.start+e.duration-1)<1.e-9,"Strum ends at exact beat");
 for(int instrument:{2,3})for(int root=0;root<12;++root)for(int style=0;style<3;++style){Settings bass;bass.instrument=instrument;bass.root=root;bass.bassPattern=style;for(bool scale:{false,true}){bass.scale=scale;auto line=makeEvents(bass);check(!line.empty(),"Bass pattern");double end=0;for(auto e:line){check(e.note>=tuning(instrument).front() && e.note<=tuning(instrument).back()+12,"Bass range");check(e.start>=end-1.e-9,"Monophonic bass");end=e.start+e.duration;}check(std::abs(end-1)<1.e-9,"Bass exact cycle length");}}
 ChordStep c;c.notes={60,64,67};ChordStep f;f.notes={77,81,84};auto before=movement(c.notes,f.notes);std::vector<ChordStep> steps{c,f};leadVoices(steps);check(movement(steps[0].notes,steps[1].notes)<before,"Reduced voice movement");std::vector<int> pc;for(int n:steps[1].notes)pc.push_back(n%12);check(uniqueNotes(pc)==std::vector<int>({0,5,9}),"Voice leading preserves harmony");
 ChordStep bass;bass.instrument=2;bass.notes={36,40,43};bass.beats=3;bass.bassPattern=1;ChordStep strummed;strummed.instrument=1;strummed.notes={48,52,55};strummed.strum=true;strummed.beats=2;events=progressionEvents({bass,strummed});check(events.size()==7 && events[4].start==3 && events[5].start>3,"Mixed instrument progression");check(std::abs(events.back().start+events.back().duration-5)<1.e-9,"Full MIDI length");
 Settings lowB;lowB.instrument=3;lowB.root=11;check(makeEvents(lowB).front().note==23,"Five-string bass uses low B");lowB.instrument=2;check(makeEvents(lowB).front().note==35,"Four-string bass B stays above low E");
 Settings g;g.instrument=1;ChordStep first;first.instrument=1;first.notes=selectedNotes(g);g.root=7;g.voicing=10;ChordStep next;next.instrument=1;next.root=7;next.notes=selectedNotes(g);next.frets=selectedFrets(g);int oldMovement=movement(first.notes,next.notes);steps={first,next};leadVoices(steps);check(movement(steps[0].notes,steps[1].notes)<=oldMovement && steps[1].notes==shapeNotes(steps[1].frets),"Guitar voice leading keeps a valid shape");
 ChordStep bassFirst; bassFirst.instrument=2;bassFirst.notes={43,47,50};ChordStep bassNext;bassNext.instrument=2;bassNext.root=0;bassNext.notes={36,40,43};steps={bassFirst,bassNext};leadVoices(steps);check(steps[1].notes.front()==48,"Bass picks closer octave");
 Settings independent;independent.instrument=2;auto baseline=selectedNotes(independent);independent.inversion=2;check(selectedNotes(independent)==baseline,"Bass ignores keyboard inversion");
 Settings inverted;inverted.instrument=1;inverted.inversion=1;check(selectedNotes(inverted).front()%12==4,"Guitar first inversion bass E");inverted.inversion=2;check(selectedNotes(inverted).front()%12==7,"Guitar second inversion bass G");check(shapeNotes(selectedFrets(inverted))==selectedNotes(inverted),"Inversion fretboard matches MIDI");
 std::cout<<"Instruments: tuning, playable ranges, complete shapes, edits, strum, bass and voice leading OK\n";
}
